cd /workspace && cat > tmp/fuzz_validate.py <<'PY'
import sys,json,random,copy,math
sys.path.insert(0,'submission')
from protocol import validate,InvalidRequest,loads
base=json.load(open('examples.json'))[1]['request']
vals=[None,True,False,0,1,-1,2.0,1e20,float('nan'),float('inf'),'','x',[],{},[1],{'x':1}]
def mut(x,depth=0):
    if depth>6:return random.choice(vals)
    r=random.random()
    if r<.12:return random.choice(vals)
    if type(x) is dict:
        y=copy.deepcopy(x)
        keys=list(y)
        if keys and random.random()<.5:
            k=random.choice(keys)
            if random.random()<.5:y[k]=mut(y[k],depth+1)
            else:del y[k]
        else:
            y[random.choice(['x','op','cases','nodes','id','rho','name','events'])]=mut(None,depth+1)
        return y
    if type(x) is list:
        y=copy.deepcopy(x)
        if y and random.random()<.5:
            i=random.randrange(len(y));y[i]=mut(y[i],depth+1)
        else:y.insert(random.randrange(len(y)+1),mut(None,depth+1))
        return y
    return x if random.random()<.5 else random.choice(vals)
random.seed(1)
unexpected=0
for i in range(30000):
    req=mut(base)
    try:
        validate(req)
    except InvalidRequest:
        pass
    except Exception as e:
        unexpected+=1;print('unexpected',type(e),e,json.dumps(req)[:1000]);break
print('done unexpected',unexpected)
# fuzz loads bytes malformed
for i in range(1000):
    raw=bytes(random.randrange(256) for _ in range(random.randint(0,100)))
    try:loads(raw)
    except InvalidRequest:pass
    except Exception as e:print('loads unexpected',type(e),e);break
else:print('loads fuzz ok')
PY
export OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 MKL_NUM_THREADS=1 LD_LIBRARY_PATH="$PWD/native" PYTHONPATH="$PWD/.deps"; python3 tmp/fuzz_validate.py
